package net.civeira.phylax.feature.access.userwebauthncredential.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.UserWebauthnCredential;
import net.civeira.phylax.feature.access.userwebauthncredential.domain.valueobject.AuthenticatorVO;

class AuthenticatorValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of authenticator of user webauthn credential")
  void test_authenticator_value_holder_assign_plain_value() {
    Object holder = new Object();
    AuthenticatorValueHolder<Object> value = new AuthenticatorValueHolder<>(holder);
    Assertions.assertSame(holder, value.authenticator("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getAuthenticatorValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getAuthenticator().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of authenticator of user webauthn credential")
  void test_authenticator_value_holder_assign_value_object() {
    Object holder = new Object();
    AuthenticatorValueHolder<Object> value = new AuthenticatorValueHolder<>(holder);
    AuthenticatorVO vo = AuthenticatorVO.from("one");
    Assertions.assertFalse(value.getAuthenticatorValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.authenticator(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAuthenticatorValue().orElseThrow());
    Assertions.assertSame(holder, value.authenticator(Optional.empty()));
    Assertions.assertFalse(value.getAuthenticatorValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.authenticator(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAuthenticatorValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of authenticator of user webauthn credential against the original")
  void test_authenticator_value_holder_read() {
    Object holder = new Object();
    AuthenticatorValueHolder<Object> value = new AuthenticatorValueHolder<>(holder);
    AuthenticatorVO vo = AuthenticatorVO.from("one");
    AuthenticatorVO other = AuthenticatorVO.from("one");
    UserWebauthnCredential original = Mockito.mock(UserWebauthnCredential.class);
    Mockito.when(original.getAuthenticatorValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAuthenticator(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readAuthenticator(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.authenticator(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAuthenticator(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAuthenticator(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of authenticator of user webauthn credential")
  void test_authenticator_value_holder_unset() {
    Object holder = new Object();
    AuthenticatorValueHolder<Object> value = new AuthenticatorValueHolder<>(holder);
    AuthenticatorVO vo = AuthenticatorVO.from("one");
    value.authenticator(vo);
    Assertions.assertSame(holder, value.unsetAuthenticatorIfMatches("authenticator_other"));
    Assertions.assertTrue(value.getAuthenticatorValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAuthenticatorIfMatches("authenticator"));
    Assertions.assertFalse(value.getAuthenticatorValue().isPresent(),
        "The field name must clear the value");
    value.authenticator(vo);
    Assertions.assertSame(holder, value.unsetAuthenticator());
    Assertions.assertFalse(value.getAuthenticatorValue().isPresent(), "Unset must clear the value");
  }
}
